module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s0_not, s1_not;
    wire and0, and1, and2, and3;

    // Generate inverted select signals
    not(s0_not, sel[0]);
    not(s1_not, sel[1]);

    // AND gates to isolate inputs based on select signals
    and(and0, in[0], s0_not, s1_not); // Select input 0
    and(and1, in[1], sel[0], s1_not); // Select input 1
    and(and2, in[2], s0_not, sel[1]); // Select input 2
    and(and3, in[3], sel[0], sel[1]); // Select input 3

    // OR gate to combine isolated inputs
    or(out, and0, and1, and2, and3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire sel0_not, sel1_not;
wire and0, and1, and2, and3;

not(sel0_not, sel[0]);
not(sel1_not, sel[1]);

and(and0, in[0], sel0_not, sel1_not);
and(and1, in[1], sel[0], sel1_not);
and(and2, in[2], sel0_not, sel[1]);
and(and3, in[3], sel[0], sel[1]);

or(out, and0, and1, and2, and3);

endmodule

