module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s0, s1, ns0, ns1;
    wire y0, y1, y2, y3;

    // Decode select signals
    assign s0 = sel[0];
    assign s1 = sel[1];
    assign ns0 = ~s0;
    assign ns1 = ~s1;

    // Condition inputs using select signals
    assign y0 = in[0] & ns1 & ns0;
    assign y1 = in[1] & ns1 & s0;
    assign y2 = in[2] & s1 & ns0;
    assign y3 = in[3] & s1 & s0;

    // Combine conditioned inputs
    assign out = y0 | y1 | y2 | y3;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s0_not, s1_not;
    wire and0, and1, and2, and3;

    // Generate NOT gates for select signals
    not (s0_not, sel[0]);
    not (s1_not, sel[1]);

    // Generate AND gates for input isolation based on select signals
    and (and0, in[0], s1_not, s0_not); // Select 00
    and (and1, in[1], s1_not, sel[0]); // Select 01
    and (and2, in[2], sel[1], s0_not); // Select 10
    and (and3, in[3], sel[1], sel[0]); // Select 11

    // Combine the isolated inputs using an OR gate
    or (out, and0, and1, and2, and3);

endmodule

