module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] current_state;

    // State encoding
    localparam A = 2'b00;
    localparam B = 2'b01;
    localparam C = 2'b10;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= A; // Initialize to state A
        end else begin
            case (current_state)
                A: current_state <= B;
                B: current_state <= C;
                C: current_state <= A;
                default: current_state <= A; // Default to state A
            endcase
        end
    end

    // Assign output
    assign state = current_state;

endmodule

