            count = 0;
            fib_0 = 0;
            fib_1 = 1;
            next_term = 0;
            done = 0;
        end
    end

    always @(posedge done or count < in_0) begin
        if (!done && count < in_0) begin
            if (count == 0) begin
                out = fib_0;
                count = count + 1;
            end else if (count == 1) begin
                out = fib_1;
                count = count + 1;
            end else begin
                next_term = fib_0 + fib_1;
                fib_0 = fib_1;
                fib_1 = next_term;
                out = next_term;
                count = count + 1;
            end
        end else begin
            done = 1;
        end
    end

endmodule

