module pipelined_adder (
    input clk, rst,
    input [15:0] a, b,
    output reg [15:0] out
);

    // Stage 1 Registers
    reg [7:0] a_stage1, b_stage1;
    reg [7:0] sum_stage1;
    reg carry_stage1;

    // Stage 2 Registers
    reg [7:0] a_stage2, b_stage2;
    reg carry_stage2;
    reg [7:0] sum_stage2;

    // Pipeline Stage 1: Lower 8-bit addition
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage1 <= 8'b0;
            b_stage1 <= 8'b0;
            sum_stage1 <= 8'b0;
            carry_stage1 <= 1'b0;
        end else begin
            a_stage1 <= a[7:0];
            b_stage1 <= b[7:0];
            {carry_stage1, sum_stage1} <= a[7:0] + b[7:0];
        end
    end

    // Pipeline Stage 2: Upper 8-bit addition
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage2 <= 8'b0;
            b_stage2 <= 8'b0;
            carry_stage2 <= 1'b0;
            sum_stage2 <= 8'b0;
        end else begin
            a_stage2 <= a[15:8];
            b_stage2 <= b[15:8];
            carry_stage2 <= carry_stage1;
            {out[16], sum_stage2} <= a_stage2 + b_stage2 + carry_stage2;
        end
    end

    // Final Output Assignment
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out <= 16'b0;
        end else begin
            out[15:8] <= sum_stage2;
            out[7:0] <= sum_stage1;
        end
    end

endmodule

module pipelined_adder (
    input clk, rst,
    input [15:0] a, b,
    output reg [15:0] out
);

    reg [8:0] stage1_sum; // Includes carry-out in bit 8
    reg [15:0] stage2_sum;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            stage1_sum <= 9'b0;
            stage2_sum <= 16'b0;
            out <= 16'b0;
        end else begin
            // Stage 1: Add lower 8 bits
            stage1_sum <= {1'b0, a[7:0]} + {1'b0, b[7:0]}; // Carry-out in stage1_sum[8]

            // Stage 2: Add upper 8 bits with carry-in from stage 1
            stage2_sum <= {8'b0, a[15:8]} + {8'b0, b[15:8]} + stage1_sum[8];

            // Combine results
            out <= {stage2_sum[15:8], stage1_sum[7:0]};
        end
    end

endmodule

module pipelined_adder (
