            stage1_carry <= 1'b0;
            stage2_sum <= 8'b0;
            stage2_carry <= 1'b0;
            out <= 16'b0;
        end else begin
            // Stage 1: Compute lower 8 bits and carry-out
            {stage1_carry, stage1_sum} <= a[7:0] + b[7:0];

            // Stage 2: Compute upper 8 bits and carry-out
            {stage2_carry, stage2_sum} <= a[15:8] + b[15:8] + stage1_carry;

            // Combine results into final output
            out <= {stage2_sum, stage1_sum};
