);

    reg [7:0] sum_stage1;
    reg carry_stage1;
    reg [7:0] sum_stage2;
    reg carry_stage2;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum_stage1 <= 8'b0;
            carry_stage1 <= 1'b0;
        end else begin
            {carry_stage1, sum_stage1} <= a[7:0] + b[7:0];
