                pp[i] <= 0;
            for (i = 0; i < 4; i = i + 1)
                sum_stage2[i] <= 0;
            final_sum <= 0;
            out <= 0;
        end else begin
            // Stage 1: Calculate partial products
            a_reg <= a;
            b_reg <= b;
            for (i = 0; i < 8; i = i + 1)
