            sum_stage2[2] <= {4'b0, pp[4], 4'b0} + {3'b0, pp[5], 5'b0};
            sum_stage2[3] <= {2'b0, pp[6], 6'b0} + {1'b0, pp[7], 7'b0};

            // Stage 3: Final addition
            final_sum <= sum_stage2[0] + sum_stage2[1] + sum_stage2[2] + sum_stage2[3];

