    input [7:0] x,
    output reg [15:0] y
);

    reg [7:0] x_reg [0:3];
    reg [7:0] coeff [0:3];
    reg [15:0] partial_product [0:3];
    reg [15:0] sum_stage1, sum_stage2;

    integer i;

    initial begin
        coeff[0] = 8'h01; // Coefficient 1
        coeff[1] = 8'h02; // Coefficient 2
        coeff[2] = 8'h03; // Coefficient 3
        coeff[3] = 8'h04; // Coefficient 4
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 4; i = i + 1) begin
                x_reg[i] <= 8'h00;
                partial_product[i] <= 16'h0000;
            end
            sum_stage1 <= 16'h0000;
            sum_stage2 <= 16'h0000;
            y <= 16'h0000;
        end else begin
            // Shift input data
            x_reg[0] <= x;
            x_reg[1] <= x_reg[0];
            x_reg[2] <= x_reg[1];
            x_reg[3] <= x_reg[2];

            // Stage 1: Compute partial products
            for (i = 0; i < 4; i = i + 1) begin
                partial_product[i] <= x_reg[i] * coeff[i];
            end

            // Stage 2: Accumulate partial products
            sum_stage1 <= partial_product[0] + partial_product[1];
            sum_stage2 <= partial_product[2] + partial_product[3];

            // Stage 3: Final accumulation
            y <= sum_stage1 + sum_stage2;
        end
    end

endmodule

