    reg [7:0] coeff [0:3];       // Coefficients for FIR filter
    reg [15:0] stage1 [0:3];     // Partial products (Stage 1)
    reg [15:0] stage2 [0:3];     // Accumulated sums (Stage 2)
    reg [15:0] stage3;           // Final accumulated sum (Stage 3)

    integer i;

    initial begin
        // Initialize coefficients (example values, can be modified)
        coeff[0] = 8'h01; // Coefficient for tap 0
        coeff[1] = 8'h02; // Coefficient for tap 1
        coeff[2] = 8'h03; // Coefficient for tap 2
        coeff[3] = 8'h04; // Coefficient for tap 3
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all pipeline registers
            for (i = 0; i < 4; i = i + 1) begin
                x_reg[i] <= 0;
                stage1[i] <= 0;
                stage2[i] <= 0;
            end
            stage3 <= 0;
            y <= 0;
        end else begin
            // Shift input samples through pipeline registers
            x_reg[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                x_reg[i] <= x_reg[i-1];
            end

            // Stage 1: Compute partial products
            for (i = 0; i < 4; i = i + 1) begin
                stage1[i] <= x_reg[i] * coeff[i];
            end

            // Stage 2: Accumulate partial products
            stage2[0] <= stage1[0];
            for (i = 1; i < 4; i = i + 1) begin
                stage2[i] <= stage2[i-1] + stage1[i];
            end

            // Stage 3: Final accumulation to produce output
            stage3 <= stage2[3];
