    reg [7:0] coeff[0:3];      // Coefficients for the filter
    reg [15:0] partial_product[0:3]; // Partial products (Stage 1)
    reg [15:0] sum_stage2[0:1];      // Intermediate sums (Stage 2)
    reg [15:0] sum_stage3;           // Final sum (Stage 3)

    integer i;

    initial begin
        coeff[0] = 8'd1; // Example coefficient values (can be changed)
        coeff[1] = 8'd2;
        coeff[2] = 8'd3;
        coeff[3] = 8'd4;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all registers
            for (i = 0; i < 4; i = i + 1) begin
                x_reg[i] <= 8'd0;
                partial_product[i] <= 16'd0;
            end
            sum_stage2[0] <= 16'd0;
            sum_stage2[1] <= 16'd0;
            sum_stage3 <= 16'd0;
            y <= 16'd0;
        end else begin
            // Shift input samples through the pipeline
            x_reg[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                x_reg[i] <= x_reg[i-1];
            end

            // Stage 1: Compute partial products
            for (i = 0; i < 4; i = i + 1) begin
                partial_product[i] <= x_reg[i] * coeff[i];
            end

            // Stage 2: Accumulate partial products in pairs
            sum_stage2[0] <= partial_product[0] + partial_product[1];
            sum_stage2[1] <= partial_product[2] + partial_product[3];

            // Stage 3: Final accumulation
            sum_stage3 <= sum_stage2[0] + sum_stage2[1];

