module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

    // Coefficients
    reg [7:0] coeff[3:0];
    initial begin
        coeff[0] = 8'd1;
        coeff[1] = 8'd2;
        coeff[2] = 8'd3;
        coeff[3] = 8'd4;
    end

    // Pipeline registers
    reg [15:0] stage1[3:0]; // Partial products
    reg [15:0] stage2[3:0]; // Partial sums
    reg [15:0] stage3;      // Final sum

    // Shift register for input samples
    reg [7:0] data[3:0];
    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset pipeline and output
            for (i = 0; i < 4; i = i + 1) begin
                stage1[i] <= 16'd0;
                stage2[i] <= 16'd0;
                data[i] <= 8'd0;
            end
            stage3 <= 16'd0;
            y <= 16'd0;
        end else begin
            // Shift input samples
            data[3] <= data[2];
            data[2] <= data[1];
            data[1] <= data[0];
            data[0] <= x;

            // Stage 1: Compute partial products
            for (i = 0; i < 4; i = i + 1) begin
                stage1[i] <= data[i] * coeff[i];
            end

            // Stage 2: Accumulate partial products
            stage2[0] <= stage1[0];
            stage2[1] <= stage1[0] + stage1[1];
            stage2[2] <= stage1[0] + stage1[1] + stage1[2];
            stage2[3] <= stage1[0] + stage1[1] + stage1[2] + stage1[3];

            // Stage 3: Final accumulation
            stage3 <= stage2[3];

            // Output result
            y <= stage3;
        end
    end
endmodule

module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

    // Coefficients for the FIR filter
    reg [7:0] coeffs [0:3];

    // Registers for pipeline stages
    reg [15:0] stage1 [0:3]; // Partial products
    reg [15:0] stage2 [0:3]; // Accumulated sums in stage 2
    reg [15:0] stage3;       // Final output

    // Input data shift register
    reg [7:0] data_reg [0:3];

    integer i;

    // Initialize coefficients (example values)
    initial begin
        coeffs[0] = 8'h01;
        coeffs[1] = 8'h02;
        coeffs[2] = 8'h03;
        coeffs[3] = 8'h04;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all pipeline registers and output
            for (i = 0; i < 4; i = i + 1) begin
                data_reg[i] <= 8'b0;
                stage1[i] <= 16'b0;
                stage2[i] <= 16'b0;
            end
            stage3 <= 16'b0;
            y <= 16'b0;
        end else begin
            // Stage 1: Shift input data and compute partial products
            data_reg[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                data_reg[i] <= data_reg[i-1];
            end

            for (i = 0; i < 4; i = i + 1) begin
                stage1[i] <= data_reg[i] * coeffs[i];
            end

            // Stage 2: Accumulate partial products
            stage2[0] <= stage1[0];
            for (i = 1; i < 4; i = i + 1) begin
                stage2[i] <= stage2[i-1] + stage1[i];
            end

            // Stage 3: Final output
            stage3 <= stage2[3];
            y <= stage3;
        end
    end

endmodule

