module compound_interest (
    input [15:0] P,
    input [7:0] r,
    input [7:0] n,
    output [31:0] A
);

    reg [31:0] result;
    reg [31:0] base;
    reg [31:0] temp;
    integer i;

    always @(*) begin
        base = 32'h10000 + {24'b0, r}; // base = 1 + r, scaled by 2^8
        temp = 32'h10000; // Start with 1 in fixed-point (scaled by 2^8)

        for (i = 0; i < n; i = i + 1) begin
            temp = (temp * base) >> 8; // Multiply and scale back
        end

        result = (P * temp) >> 8; // Multiply principal with (1 + r)^n and scale back
    end

    assign A = result;

endmodule

