module ddm_calculator (
    input [15:0] expected_dividend,  // 16-bit unsigned integer
    input [7:0] required_rate,       // 8-bit fixed-point integer
    input [7:0] growth_rate,         // 8-bit fixed-point integer
    output reg [31:0] ddm_value      // 32-bit unsigned integer
);

    reg [15:0] required_rate_frac;   // Fractional value of required rate
    reg [15:0] growth_rate_frac;     // Fractional value of growth rate
    reg [15:0] denominator;          // Denominator for DDM calculation
    reg valid_denominator;           // Flag for valid denominator

    always @(*) begin
        // Convert fixed-point inputs to fractional values
        required_rate_frac = required_rate * 16'd256; // Equivalent to dividing by 256
        growth_rate_frac = growth_rate * 16'd256;     // Equivalent to dividing by 256

        // Compute the denominator
        if (required_rate_frac > growth_rate_frac) begin
            denominator = required_rate_frac - growth_rate_frac;
            valid_denominator = 1'b1;
        end else begin
            denominator = 16'd0;
            valid_denominator = 1'b0;
        end

        // Compute DDM value if the denominator is valid
        if (valid_denominator) begin
            ddm_value = expected_dividend * 16'd256 / denominator; // Scale dividend and divide
        end else begin
            ddm_value = 32'd0; // Output zero for invalid denominator
        end
    end

endmodule

