module feistel_encrypt(
    input [7:0] plaintext,
    output [7:0] ciphertext
);

    // Fixed key for XOR operation
    parameter [3:0] KEY = 4'b1010;

    // Split input into left and right halves
    wire [3:0] left_half = plaintext[7:4];
    wire [3:0] right_half = plaintext[3:0];

    // Apply round function (XOR with KEY) to right-half
    wire [3:0] round_output = right_half ^ KEY;

    // XOR round function output with left-half
    wire [3:0] new_right_half = left_half ^ round_output;

    // Swap halves to form ciphertext
    assign ciphertext = {right_half, new_right_half};

endmodule

