module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    // Internal signals for intermediate terms
    wire signed [15:0] T_ext, R_ext; // Extended temperature and humidity
    wire signed [31:0] term1, term2, term3, term4, term5, term6, term7, term8, term9; // Polynomial terms
    wire signed [31:0] T_sq, R_sq; // Squared temperature and humidity
    wire signed [31:0] T_sq_R, T_R_sq, T_sq_R_sq; // Mixed higher-order terms
    wire signed [31:0] sum; // Final sum

    // Sign extension of inputs
    assign T_ext = {8'b0, temperature};
    assign R_ext = {8'b0, humidity};

    // Polynomial terms
    assign term1 = C1; // Constant term
    assign term2 = C2 * T_ext; // Direct weighted term C2*T
    assign term3 = C3 * R_ext; // Direct weighted term C3*R
    assign term4 = C4 * T_ext * R_ext; // Interaction term C4*T*R
    assign T_sq = T_ext * T_ext; // T^2
    assign R_sq = R_ext * R_ext; // R^2
    assign term5 = C5 * T_sq; // Quadratic term C5*T^2
    assign term6 = C6 * R_sq; // Quadratic term C6*R^2
    assign T_sq_R = T_sq * R_ext; // Mixed term T^2*R
    assign T_R_sq = T_ext * R_sq; // Mixed term T*R^2
    assign T_sq_R_sq = T_sq * R_sq; // Mixed term T^2*R^2
    assign term7 = C7 * T_sq_R; // C7*T^2*R
    assign term8 = C8 * T_R_sq; // C8*T*R^2
    assign term9 = C9 * T_sq_R_sq; // C9*T^2*R^2

    // Final summation
    assign sum = term1 + term2 + term3 + term4 + term5 + term6 + term7 + term8 + term9;

    // Output heat index (truncate to 16 bits)
    assign heat_index = sum[15:0];

endmodule

module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

