    wire signed [31:0] term_C7T2R, term_C8TR2, term_C9T2R2;
    wire signed [31:0] sum;

    // Convert temperature and humidity to signed 16-bit values
    assign T = {8'b0, temperature};
    assign R = {8'b0, humidity};

    // Compute square of temperature and humidity
    assign T_squared = T * T;
    assign R_squared = R * R;

    // Compute individual terms
    assign term_C2T = C2 * T;
    assign term_C3R = C3 * R;
    assign term_C4TR = C4 * T * R;
    assign term_C5T2 = C5 * T_squared;
    assign term_C6R2 = C6 * R_squared;
    assign term_C7T2R = C7 * T_squared * R;
    assign term_C8TR2 = C8 * T * R_squared;
    assign term_C9T2R2 = C9 * T_squared * R_squared;

    // Accumulate all terms into the final sum
    assign sum = C1 + term_C2T + term_C3R + term_C4TR + term_C5T2 + term_C6R2 + term_C7T2R + term_C8TR2 + term_C9T2R2;

    // Truncate the final sum to 16-bit signed value
    assign heat_index = sum[15:0];

endmodule

